#!/usr/bin/env python3
"""Generate source-only sign18 per-row evaluation transfers from staged rows."""
import hashlib,json,sys
from pathlib import Path
if not sys.flags.isolated or not sys.flags.no_site or sys.flags.optimize:raise SystemExit('use python3 -I -S -B')
here=Path(__file__).resolve().parent;src=here.parent/'nine-sharing-sign18-degree94-root-candidate/seed.json';raw=src.read_bytes();assert hashlib.sha256(raw).hexdigest()=='d3fd0a00ed9f803a5c002481dbfb22aafe9a5ba34ac89c90069cefbdcaada3fb';d=json.loads(raw);names=[r['gate'] for r in d['residuals']];assert names==['Dc2','tau','N0','Nt','cTminusR','V','V2minusY2','Na','scaled_Ns']
shared=', '.join(f'SharingSeed18Degree94.shared{i:02}' for i in range(35))
for i,n in enumerate(names):
 assert n.isidentifier();p=here/f'Sign18Transfer{i:02}.lean'
 if p.exists():raise SystemExit('refusing overwrite '+str(p))
 p.write_text(f'''import DiophantineConsistency.Sign18Coordinate\n\n/-! SOURCE-ONLY individual staged residual transfer. -/\nset_option autoImplicit false\nnoncomputable section\nnamespace DiophantineConsistency.Sign18Transfers\nopen LO LO.FirstOrder LO.FirstOrder.Arithmetic ModelDifferenceRing\nopen scoped LO.FirstOrder LO.FirstOrder.Arithmetic\nopen AdaptiveEquationSyntax2011\nvariable {{V : Type}} [ORingStructure V] [V↓[ℒₒᵣ] ⊧* 𝗜𝚺₁]\n\ndef old{n} (p : Fin 4 → ℤ) : Expr (Fin 20) := SharingSeed19Degree44.row{i+1:02} p\ndef new{n} (p : Fin 4 → ℤ) : Expr (Fin 19) := SharingSeed18Degree94.row{i:02} p\n\ntheorem old_{n}_row (p : Fin 4 → ℤ) :\n    ((SharingSeed19Degree44.remainingResiduals p).drop {i}).head? = some (old{n} p) := by rfl\n\ntheorem new_{n}_row (p : Fin 4 → ℤ) :\n    '''+(f'SharingSeed18Degree94.firstResidual p = new{n} p' if i==0 else f'((SharingSeed18Degree94.remainingResiduals p).drop {i-1}).head? = some (new{n} p)')+f''' := by rfl\n\ntheorem {n}_eval (p : Fin 4 → ℤ) (beta : V) (v : Fin 19 → V)\n    (hp0 : ((p 0 : ℤ) : DiffRing V) = ι beta) :\n    (old{n} p).evalRing (fun j => ι (Sign18Coordinate.lift beta v j)) =\n      (new{n} p).evalRing (fun j => ι (v j)) := by\n  simp [old{n}, new{n}, SharingSeed19Degree44.row{i+1:02}, SharingSeed18Degree94.row{i:02},\n    {shared}, Sign18Coordinate.lift, Sign18Coordinate.rootValue, Expr.evalRing_sub,\n    Expr.evalRing_mul, Expr.evalRing_add, Expr.evalRing_var, Expr.evalRing_constant,\n    map_add, map_mul, map_ofNat, hp0]\nend DiophantineConsistency.Sign18Transfers\n#print axioms DiophantineConsistency.Sign18Transfers.{n}_eval\n''')
print(json.dumps({'status':'GENERATED_SOURCE_ONLY','transfers':len(names),'scope':'No Lean compilation or model bridge.'},indent=2,sort_keys=True))
